using System.Net;
using System.Net.Sockets;
using System.Text;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>A real local HTTP server standing in for the provider; records what it receives.</summary>
internal sealed class FakeProvider : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly int status;
    private readonly string body;
    private readonly string contentType;
    private readonly Task loop;

    public FakeProvider(int status, string body, string contentType = "application/json")
    {
        this.status = status;
        this.body = body;
        this.contentType = contentType;

        var probe = new TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();

        BaseAddress = new Uri($"http://127.0.0.1:{port}");
        listener.Prefixes.Add($"{BaseAddress}");
        listener.Start();
        loop = Task.Run(ServeAsync);
    }

    public Uri BaseAddress { get; }
    public string? Method { get; private set; }
    public string? Path { get; private set; }
    public string? RequestContentType { get; private set; }
    public string? RequestBody { get; private set; }
    public int RequestCount { get; private set; }

    private async Task ServeAsync()
    {
        try
        {
            while (true)
            {
                var context = await listener.GetContextAsync();
                using (var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8))
                    RequestBody = await reader.ReadToEndAsync();
                Method = context.Request.HttpMethod;
                Path = context.Request.Url!.AbsolutePath;
                RequestContentType = context.Request.ContentType;
                RequestCount++;

                var bytes = Encoding.UTF8.GetBytes(body);
                context.Response.StatusCode = status;
                context.Response.ContentType = contentType;
                context.Response.ContentLength64 = bytes.Length;
                await context.Response.OutputStream.WriteAsync(bytes);
                context.Response.Close();
            }
        }
        catch (Exception) when (!listener.IsListening)
        {
        }
    }

    public void Dispose()
    {
        listener.Close();
        loop.Wait(TimeSpan.FromSeconds(5));
    }
}
