using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    private static Task<AuthorizationOutcome> Authorize(FakeProvider provider, string reference = "ORD-7", decimal amount = 12.50m, string currency = "eur")
    {
        using var client = new HttpClient { BaseAddress = provider.BaseAddress };
        return new HttpPaymentGateway(client).AuthorizeAsync(reference, new Money(amount, currency), CancellationToken.None);
    }

    [Fact]
    public async Task The_request_is_a_json_post_to_the_authorizations_endpoint()
    {
        using var provider = new FakeProvider(200, """{"status":"approved"}""");

        await Authorize(provider);

        Assert.Equal("POST", provider.Method);
        Assert.Equal("/v1/authorizations", provider.Path);
        Assert.StartsWith("application/json", provider.RequestContentType);
    }

    [Fact]
    public async Task The_request_body_carries_reference_amount_and_normalised_currency()
    {
        using var provider = new FakeProvider(200, """{"status":"approved"}""");

        await Authorize(provider, "ORD-7", 12.50m, "eur");

        using var sent = JsonDocument.Parse(provider.RequestBody!);
        var root = sent.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_status_is_read_as_approved()
    {
        using var provider = new FakeProvider(200, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize(provider));
    }

    [Fact]
    public async Task A_declined_status_is_read_as_declined()
    {
        using var provider = new FakeProvider(200, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(provider));
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        using var provider = new FakeProvider(200, """{"id":"auth_1","status":"approved","risk":{"score":3}}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize(provider));
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_even_with_an_error_body()
    {
        using var provider = new FakeProvider(402, """{"error":"card_refused"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(provider));
        Assert.Equal(1, provider.RequestCount);
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_with_an_empty_body()
    {
        using var provider = new FakeProvider(402, "");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(provider));
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(404)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_error_statuses_are_failures_not_declines(int status)
    {
        using var provider = new FakeProvider(status, """{"status":"approved"}""");

        var error = await Assert.ThrowsAsync<HttpRequestException>(() => Authorize(provider));
        Assert.Equal((System.Net.HttpStatusCode)status, error.StatusCode);
    }

    [Fact]
    public async Task An_answer_that_is_not_json_is_a_failure()
    {
        using var provider = new FakeProvider(200, "<html>oops</html>", "text/html");

        await Assert.ThrowsAnyAsync<Exception>(() => Authorize(provider));
    }

    [Fact]
    public async Task A_malformed_json_answer_is_a_failure()
    {
        using var provider = new FakeProvider(200, """{"status":""");

        await Assert.ThrowsAsync<JsonException>(() => Authorize(provider));
    }

    [Theory]
    [InlineData("""{}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"decision":"approved"}""")]
    [InlineData("""null""")]
    public async Task An_answer_that_does_not_clearly_say_approved_is_never_treated_as_approved(string answer)
    {
        using var provider = new FakeProvider(200, answer);

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(provider));
    }
}
EOF
